# Minimal recursive schema validator suffices for this schema; no third-party install.
def validate(v,s,path='$'):
 if 'type' in s:
  typ=s['type']; ok={'object':isinstance(v,dict),'array':isinstance(v,list),'string':isinstance(v,str),'integer':type(v)is int,'number':isinstance(v,(int,float)) and not isinstance(v,bool)}[typ]
  assert ok,(path,typ)
 if 'enum' in s:assert v in s['enum'],path
 if isinstance(v,dict):
  assert all(k in v for k in s.get('required',[])),path
  if s.get('additionalProperties') is False:assert set(v)<=set(s.get('properties',{})),path
  for k,val in v.items():
   if k in s.get('properties',{}):validate(val,s['properties'][k],path+'.'+k)
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),path
  for i,val in enumerate(v):validate(val,s.get('items',{}),path+f'[{i}]')
 if isinstance(v,str):assert len(v)>=s.get('minLength',0),path
 if type(v) in (int,float):
  assert v>=s.get('minimum',float('-inf')) and v<=s.get('maximum',float('inf')),path
